class DeveloperInterface(object):

    def __init__(self, connection):
        self.connection = connection

    @staticmethod
    def get_dsp_mode2(board, cpu, humanize=True):
        """
        Get mode of a selected CPU

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                                                  |
        +================+======+==============================================================================================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13                                                                                   |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81                                                                               |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | humanize       | No   | determines output format: as a simple integer (``${False}``), or as a descriptive string (``${True}``)       |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get DSP Mode    0x12    0x31    humanize=${False}
            -> 9

        **Example:**

        .. code-block:: robotframework

            ${mode}=    Get DSP Mode    0x12    0x31
            -> [mode_09]NyquistCommonChannelDeviceNormal

        | **Return value:**
        | DSP mode
        """
        board, cpu = intlify(board, cpu)
        _, _, mode = DspModeInterface().get_dsp_mode(board, cpu, humanize)
        return mode

    def get_browser_sw_version(self, board, cpu):
        """
        Get version of WCDMA Signal Processing Software (WSP SW)

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${version}=    Get Browser SW Version    0x12    0x31
            -> BTS_SC_DSP/branches/SBTS17A_R3 @Revision: 128607 SwBuild: `date+%Y-%m-%dT%T` os320c66x_R414_BPSH8M51

        | **Return value:**
        | a string with the version of WSP SW currently available on BTS
        """
        board, cpu = intlify(board, cpu)
        version = MiscInterface(self.connection).get_browser_sw_version(board, cpu)
        return version

    def get_cell_ids(self, board, cpu):
        """
        Get a list of WCDMA cells handled by selected CPU

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${cells}= | Get Cell IDs | 0x13 | 0x31 |
            ->  [29101, 29103]

        | **Return value:**
        | a list of cell IDs
        """
        board, cpu = intlify(board, cpu)
        return CellListInterface(self.connection).get_cell_ids(board, cpu)

