    def get_services(self, board, cpu, humanize=True):
        """
        Get list of services available for a selected CPU

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                                                  |
        +================+======+==============================================================================================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13                                                                                   |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81                                                                               |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | humanize       | No   | determines output format: as a simple integer (``${False}``), or as a descriptive string (``${True}``)       |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${services}=    Get Services    0x12    0x31
            ->  [('0x13', '0x31', 'Bts', 'SFN(0x1BE9)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'General Report(0x1E0D)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'StopGeneralReport(0x1E0E)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'TimerServerTimeoutInd(0xF030)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF032)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF03A)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF03C)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF034)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF036)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Unknown(0xF038)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Bts', 'Get Version(0x1B25)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Cpu', 'CPU Load(0x1BE4)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Cpu', 'StopIdleMeasurement(0x1BE5)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Cpu', 'Idle Measurement(0x1BE6)', 'Unknown(65535)'),
             ('0x13', '0x31', 'Cpu', 'CPU Load(0x1E17)', 'Unknown(65535)'),
             ...
             ]

        | **Return value:**
        | a list of available services as tuples: (board, cpu, object_type, message_id, available_service)
        """
        board, cpu = intlify(board, cpu)
        return ServiceInterface(self.connection).get_services(board, cpu, humanize)

    def get_services_for_chip(self, board, chip, humanize=True):
        """
        Get all services available on a selected chip

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                                                  |
        +================+======+==============================================================================================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13                                                                                   |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | chip           | Yes  | chip id, e.g., 0x30                                                                                          |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | humanize       | No   | determines output format: as a simple integer (``${False}``), or as a descriptive string (``${True}``)       |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+

        See the doc for ``get_services``
        """
        board, chip = intlify(board, chip)
        return ServiceInterface(self.connection).get_services_for_chip(board, chip, humanize)

    def get_services_for_board(self, board, humanize=True):
        """
        Get all services for all CPUs on a selected board

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 1.0.0

        **Input parameters:**

        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | Parameter name | Man. | Description                                                                                                  |
        +================+======+==============================================================================================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13                                                                                   |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+
        | humanize       | No   | determines output format: as a simple integer (``${False}``), or as a descriptive string (``${True}``)       |
        +----------------+------+--------------------------------------------------------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${services}=    Get Services For Board    0x13

        See the doc for ``get_services``
        """
        board = intlify(board)[0]
        return ServiceInterface(self.connection).get_services_for_board(board, humanize)

