    def get_radio_link_ids(self, board, cpu):
        """
        Get a list of radio link IDs for a given CPU

        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** ---

        **Input parameters:**

        +----------------+------+----------------------------------+
        | Parameter name | Man. | Description                      |
        +================+======+==================================+
        | board          | Yes  | board id, e.g., 0x12, 0x13       |
        +----------------+------+----------------------------------+
        | cpu            | Yes  | CPU id, e.g., 0x31, 0x32, 0x81   |
        +----------------+------+----------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${rl_ids}=    Get Radio Link IDs    0x13    0x31
            ->  [1]
        """
        board, cpu = intlify(board, cpu)
        user_ids = UserListInterface(self.connection).get_user_ids(board, cpu)

        try:
            user_id = user_ids[0]
        except IndexError:
            return []
        return RadioLinkListInterface(self.connection).get_radio_link_ids(board, cpu, user_id)

    def get_cell_channel_list(self, board, cpu, cell_id):
        board, cpu, cell_id = intlify(board, cpu, cell_id)
        return ChannelListInterface(self.connection).get_cell_channel_list(board, cpu, cell_id)

    def get_cpu_with_service(self, service_or_message_id, humanize=True):
        return ServiceInterface(self.connection).get_board_cpu_pairs_with_given_service_or_message(service_or_message_id, humanize)
